const mark=k=>'<span class="mark">'+icon(k)+'</span>';
const link=(href,label,secondary=false)=>'<a class="btn'+(secondary?' secondary':'')+'" href="'+href+'">'+label+icon('arrow')+'</a>';
const title='Project Zero — From idea to operating business';
const description='Plan your business, choose the right platforms, prioritize development and prepare to launch. Explore free platform pricing guides and a guided project workflow.';
const compare=[['cloudflare-vs-vercel-vs-netlify','cloud','Cloudflare vs Vercel vs Netlify','Compare hosting, deployment options and commercial plan requirements.'],['stripe-vs-paddle-vs-lemon-squeezy','wallet','Stripe vs Paddle vs Lemon Squeezy','Understand transaction fees, checkout and merchant-of-record responsibilities.'],['d1-vs-supabase-vs-firebase','layers','D1 vs Supabase vs Firebase','Compare databases, data models and the cost of supporting your app.']];
const html='<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><meta name="description" content="'+description+'"><meta name="robots" content="index, follow"><link rel="canonical" href="'+BASE+'/"><meta name="theme-color" content="#ffffff"><link rel="icon" href="/favicon-v2.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:site_name" content="Project Zero"><meta property="og:title" content="'+title+'"><meta property="og:description" content="'+description+'"><meta property="og:url" content="'+BASE+'/"><meta property="og:image" content="https://www.projectzero.work/og/projectzero-v1.png"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Project Zero — From idea to operating business"><meta name="twitter:image" content="https://www.projectzero.work/og/projectzero-v1.png"><meta name="twitter:image:alt" content="Project Zero — From idea to operating business"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'+title+'"><meta name="twitter:description" content="'+description+'"><script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'WebSite','@id':BASE+'/#website',name:'Project Zero',url:BASE+'/'},{'@type':'WebPage','@id':BASE+'/#page',url:BASE+'/',name:title,description,inLanguage:'en-US',isPartOf:{'@id':BASE+'/#website'}}]})+'</script><style>'+CSS+'</style><style>.pz-analytics-choice{position:fixed;bottom:12px;left:12px;right:12px;z-index:100;max-width:480px;margin:auto;border:1px solid #dce0e4;background:#fff;color:#191919;border-radius:10px;box-shadow:0 6px 32px #0002;padding:12px 14px;font:13px/1.45 system-ui,sans-serif}.pz-analytics-choice[hidden]{display:none!important}.pz-analytics-choice p{margin:4px 0 9px;font-size:12px}.pz-analytics-actions{display:flex;flex-wrap:wrap;gap:8px}.pz-analytics-actions button{min-height:44px;min-height:44px;padding:8px 12px;background:#191919;color:#fff;border:1px solid #191919;border-radius:7px;font:inherit;cursor:pointer}.pz-analytics-actions button[data-deny]{background:#fff;color:#191919;border-color:#dce0e4}.pz-analytics-settings{font:inherit;color:inherit;background:none;border:0;padding:0;text-decoration:underline;cursor:pointer}.pz-analytics-choice button:focus-visible,.pz-analytics-settings:focus-visible{outline:2px solid #52657e;outline-offset:3px}</style></head><body><a href="#main" class="skip">Skip to content</a><header><nav class="wrap" aria-label="Main navigation"><a class="brand" href="/"><img src="/logo.svg" width="36" height="36" alt="">Project Zero</a><div class="navlinks"><a class="desktop" href="#workflow">How it works</a><a class="desktop" href="#features">Features</a><a href="'+GUIDES+'/platforms">Guides</a><a href="/demo">Demo</a><a class="btn secondary" href="https://account.projectzero.work/">Sign in</a></div></nav></header><main id="main"><section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow"><span class="dot"></span>Business development workspace</div><h1>From idea to<br>operating business.</h1><p class="lead">Build with a plan. Choose the right services, coordinate development, verify your launch and keep the business in view — one step at a time.</p><div class="actions">'+link('https://account.projectzero.work/','Sign in')+link('/demo','Try the demo',true)+'</div><p class="small">Explore the interactive demo and public guides without an account.</p></div><div class="preview" aria-label="Illustrative project workspace with sample values"><div class="previewhead"><span>Project Zero / Lifecycle</span><a class="small" href="/demo">TRY INTERACTIVE DEMO →</a></div><div class="previewbody"><div class="projectline">'+mark('layers')+'<div>Example SaaS project<small>Sample project · not live customer data</small></div></div><div class="progress" aria-hidden="true">'+Array.from({length:7},()=>'<i></i>').join('')+'</div><div class="small">3 of 7 review checkpoints approved (example)</div><div class="previewrail">'+steps.map(([k,label],i)=>'<div'+(i===4?' class="current"':'')+'>'+icon(k)+label+'</div>').join('')+'</div><div class="mock-card"><h2>Next development priorities</h2><div class="mocktask"><span class="p0">P0</span>Test customer sign-in<span>In progress</span></div><div class="mocktask"><span class="p0">P0</span>Verify checkout &amp; delivery<span>Not started</span></div><div class="mocktask"><span class="p1">P1</span>Improve onboarding<span>Not started</span></div></div><div class="mockstats"><div><small>Monthly budget (sample)</small><strong>$10</strong><small>Set your own limit</small></div><div><small>Planned cost (sample)</small><strong>$5</strong><small>Estimate, not actual spend</small></div></div></div></div></div></section><section id="features" class="section"><div class="wrap"><div class="sectionhead"><span class="eyebrow">One workspace, clear priorities</span><h2>Everything starts with a plan.</h2><p>Project Zero is designed to help independent founders and small teams move from scattered ideas and tools to a structured workflow. Explore project planning and development tasks in the interactive demo.</p></div><div class="featuregrid">'+features.map(([k,t,d])=>'<article class="feature">'+mark(k)+'<h3>'+t+'</h3><p>'+d+'</p></article>').join('')+'</div></div></section><section class="section alt" id="workflow"><div class="wrap"><div class="sectionhead"><span class="eyebrow">The lifecycle</span><h2>Eight steps. One clear direction.</h2><p>Start a new idea or bring an existing project. Follow the guided steps, or use advanced settings when you need more control.</p></div><div class="steps">'+steps.map(([k,t,d],i)=>'<article class="step"><div class="stephead">'+mark(k)+'<small>0'+(i+1)+'</small></div><h3>'+t+'</h3><p>'+d+'</p></article>').join('')+'</div></div></section><section class="section"><div class="wrap"><div class="sectionhead"><span class="eyebrow">Bring your own workflow</span><h2>Use AI. Or don’t.</h2><p>Keep the tools you already use. A paid AI account is not required for manual project planning.</p></div><div class="workgrid">'+[['list','Manual','Plan and manage work yourself, track evidence and make decisions at your own pace.'],['bot','AI-assisted','Use project-specific prompts with ChatGPT or Claude. Review generated tasks and configure supported schedules in your own account.'],['users','Mixed','Let assistants handle approved development work while you control spending, credentials, security and launch approval.']].map(([k,t,d])=>'<article class="workcard">'+mark(k)+'<h3>'+t+'</h3><p>'+d+'</p></article>').join('')+'</div><p class="small">Account access, scheduling and external tool availability depend on your chosen plan. Project Zero does not grant permissions or create schedules automatically.</p></div></section><section class="section alt" id="guides"><div class="wrap"><div class="sectionhead"><span class="eyebrow">Public resource library</span><h2>Find the tools that fit your business.</h2><p>Read platform pricing, benefits and tradeoffs without creating an account. Compare costs before choosing services.</p></div><div class="comparegrid">'+compare.map(([slug,k,t,d])=>'<a class="compare" href="'+GUIDES+'/compare/'+slug+'">'+mark(k)+'<h3>'+t+'</h3><p>'+d+'</p><span class="link">Read comparison '+icon('arrow')+'</span></a>').join('')+'</div><div class="actions">'+link(GUIDES+'/platforms','Browse platform directory')+link(GUIDES+'/tools','Cost calculators',true)+link(GUIDES+'/setups','Setup tutorials',true)+'</div></div></section><section class="section" id="faq"><div class="wrap"><div class="sectionhead"><span class="eyebrow">Frequently asked questions</span><h2>Before you get started.</h2></div><div class="faq">'+faqs.map(([q,a])=>'<details><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'</div></div></section><section class="section"><div class="wrap"><div class="cta"><div><h2>Your next project starts here.</h2><p>Explore the demo or sign in to your account.</p></div><a class="btn" href="https://account.projectzero.work/">Sign in '+icon('arrow')+'</a></div></div></section></main><footer class="foot"><div class="wrap footrow"><span>Project Zero · Public product overview</span><div class="footlinks"><a href="'+GUIDES+'/methodology">Editorial policy &amp; disclosures</a><a href="'+GUIDES+'/">Platform guides</a><a href="'+WORKSPACE+'/">Private workspace sign in</a><button id="pz-analytics-settings" class="pz-analytics-settings" type="button">Analytics preferences</button><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Service</a></div></div></footer><script src="/assets/session-v2.js" defer></script><aside id="pz-analytics-choice" class="pz-analytics-choice" data-site="__PZ_PUBLIC_ANALYTICS_SITE__" aria-label="Analytics preferences" hidden><strong>Optional site analytics</strong><p>Allow SiteAPT to measure public page visits, referrers and link or calculator usage. It does not receive calculator values. Analytics is off unless you allow it. <a href="/privacy">Privacy information</a>.</p><div class="pz-analytics-actions"><button type="button" data-allow>Allow analytics</button><button type="button" data-deny>No thanks</button></div></aside><script src="/assets/analytics-v1.js" defer></script></body></html>';
